import fs from 'node:fs/promises';
import path from 'node:path';
import type { Locator, Page } from 'playwright';
import type { PlannedAction, StepTrace } from '../shared/types.js';

export interface NetworkEvidence { method:string; url:string; status?:number; requestBody?:unknown; responseBody?:unknown }

export function installNetworkInstrumentation(page: Page, sink: NetworkEvidence[]): void {
  page.on('request', req => {
    let body: unknown;
    try { body = req.postDataJSON(); } catch { body = req.postData(); }
    sink.push({method:req.method(),url:req.url(),requestBody:body});
  });
  page.on('response', async res => {
    const row = [...sink].reverse().find(x => x.url === res.url() && x.status === undefined);
    if (!row) return;
    row.status = res.status();
    try { row.responseBody = await res.json(); } catch { row.responseBody = await res.text().catch(()=>undefined); }
  });
}

export async function elementSnapshot(locator: Locator) {
  return locator.evaluate(el => {
    const h = el as HTMLElement; const input = el as HTMLInputElement;
    return {
      tagName: el.tagName.toLowerCase(), role: el.getAttribute('role'),
      accessibleName: el.getAttribute('aria-label') || h.innerText?.trim() || null,
      testId: el.getAttribute('data-testid'), visibleText: h.innerText?.trim() || null,
      inputType: input.type || null, value: input.value ?? null
    };
  });
}

export async function buildStepTrace(args:{page:Page;action:PlannedAction;locator:Locator;beforeValue:string|null;network:NetworkEvidence[];artifactDir:string}):Promise<StepTrace>{
  await fs.mkdir(args.artifactDir,{recursive:true});
  const before = path.join(args.artifactDir,`${args.action.stepId}-before.png`);
  const after = path.join(args.artifactDir,`${args.action.stepId}-after.png`);
  await args.page.screenshot({path:before});
  const snap = await elementSnapshot(args.locator);
  await args.page.screenshot({path:after});
  const valueAfter = await args.locator.inputValue().catch(()=>null);
  const visibleTexts = await args.page.locator('body').innerText().then(t=>t.split(/\n+/).map(x=>x.trim()).filter(Boolean));
  return {
    stepId:args.action.stepId,requested:args.action,url:args.page.url(),title:await args.page.title(),
    beforeScreenshot:before,afterScreenshot:after,
    element:{...snap,valueBefore:args.beforeValue,valueAfter},
    locatorCandidates:[
      ...(snap.testId?[{type:'TEST_ID' as const,value:snap.testId,unique:await args.page.getByTestId(snap.testId).count()===1,score:100}]:[]),
      ...(snap.accessibleName?[{type:'ROLE' as const,value:snap.accessibleName,unique:await args.page.getByRole(snap.role as any||'button',{name:snap.accessibleName}).count().catch(()=>0)===1,score:90}]:[])
    ],
    waitCondition:null,network:args.network,stateAfter:{visibleTexts},warnings:[]
  };
}

export function completeness(trace: StepTrace): {ratio:number;missing:string[]} {
  const checks:[string,boolean][]=[
    ['stepId',!!trace.stepId],['requested',!!trace.requested],['url',trace.url!==undefined],['title',!!trace.title],
    ['beforeScreenshot',!!trace.beforeScreenshot],['afterScreenshot',!!trace.afterScreenshot],['element.tagName',!!trace.element.tagName],
    ['accessibleName',!!trace.element.accessibleName],['locatorCandidates',trace.locatorCandidates.length>0],['stateAfter',trace.stateAfter.visibleTexts.length>0]
  ];
  const missing=checks.filter(([,ok])=>!ok).map(([k])=>k); return {ratio:(checks.length-missing.length)/checks.length,missing};
}

